<script setup lang="ts">
import {computed} from 'vue'
import type {Row} from '../types'
import {money,text} from '../format'
import UiIcon from '../components/UiIcon.vue'
import StatusBadge from '../components/StatusBadge.vue'

const props=defineProps<{quota:Row}>()
const spent=computed(()=>Number(props.quota.spent_micros)||0)
const reserved=computed(()=>Number(props.quota.reserved_micros)||0)
const budget=computed(()=>Number(props.quota.budget_micros)||0)
const spentWidth=computed(()=>budget.value>0?Math.min(100,spent.value/budget.value*100):0)
const reservedWidth=computed(()=>budget.value>0?Math.min(100-spentWidth.value,reserved.value/budget.value*100):0)
const available=computed(()=>Math.max(0,budget.value-spent.value-reserved.value))
const states=computed<Row[]>(()=>Array.isArray(props.quota.states)?props.quota.states:[])
const unknown=computed(()=>states.value.find(state=>state.status==='UNKNOWN')?.count||0)
</script>

<template>
  <div class="quota-view">
    <div class="quota-summary" aria-label="组织预算概览">
      <section class="quota-number"><div class="quota-label"><span>已计用量</span><UiIcon name="quota" :size="17"/></div><strong>{{money(quota.spent_micros)}}</strong><p>按已记录 token 的保守估算</p></section>
      <section class="quota-number reserved-number"><div class="quota-label"><span>预留与未知占用</span><UiIcon name="clock" :size="17"/></div><strong>{{money(quota.reserved_micros)}}</strong><p>结果未确认的调用继续保留占用</p></section>
      <section class="quota-number"><div class="quota-label"><span>组织预算上限</span><UiIcon name="lock" :size="17"/></div><strong>{{money(quota.budget_micros,2)}}</strong><p>当前工作空间的模型调用额度</p></section>
    </div>
    <section class="budget-panel" aria-labelledby="budget-heading"><div class="section-heading"><div><h2 id="budget-heading">预算使用情况</h2></div><span class="available-amount">可用额度 <strong>{{money(available)}}</strong></span></div><div class="budget-track" role="img" :aria-label="`预算上限 ${money(budget)}，已计用量 ${money(spent)}，预留与未知占用 ${money(reserved)}，可用额度 ${money(available)}`"><span class="spent-segment" :style="{width:spentWidth+'%'}"></span><span class="reserved-segment" :style="{width:reservedWidth+'%'}"></span></div><div class="budget-legend"><span><i class="spent-dot" aria-hidden="true"></i>已计用量</span><span><i class="reserved-dot" aria-hidden="true"></i>预留与未知占用</span><span><i class="available-dot" aria-hidden="true"></i>可用额度</span></div><p class="budget-note">调用前先预留，确认结果后结算。以上为系统记账口径，与供应商最终账单可能存在差异。</p></section>
    <div class="quota-details"><section class="resource-panel" aria-labelledby="resource-heading"><div class="section-heading"><div><h2 id="resource-heading">资源边界</h2></div><UiIcon name="settings" :size="18"/></div><dl class="resource-list"><div><dt>待处理任务上限</dt><dd>{{quota.max_pending}}<span>项</span></dd></div><div><dt>组织同时执行上限</dt><dd>{{quota.max_running}}<span>项</span></dd></div></dl><div class="unknown-note"><UiIcon name="alert" :size="17"/><p><strong>{{unknown?'有 '+unknown+' 项调用结果未知':'关于未知调用'}}</strong><span>结果不明时保留预算占用。重试需要明确确认，可能再次产生调用与费用。</span></p></div></section>
    <section class="state-panel" aria-labelledby="states-heading"><div class="section-heading"><div><h2 id="states-heading">任务状态分布</h2></div></div><div v-for="state in states" :key="state.status" class="quota-state-row"><StatusBadge :value="state.status"/><span :aria-label="`${text(state.status)} ${state.count} 项`">{{state.count}}<small> 项</small></span></div><p v-if="!states.length" class="no-states">当前组织还没有任务记录。</p></section></div>
  </div>
</template>

<style scoped>
