grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.resource-list{display:block;padding:0;margin:0}.resource-list>div{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:18px 0;border-top:1px solid var(--line)}.resource-list dt{font-size:14px;line-height:1.7;color:var(--muted)}.resource-list dd{margin:0;font-size:20px;font-weight:550;line-height:1.5;font-variant-numeric:tabular-nums}.resource-list dd>span{font-size:12px;color:var(--muted);font-weight:400;margin-left:9px}.unknown-note{display:flex;align-items:flex-start;gap:10px;background:#fbf6ed;border:1px solid #eee0c6;border-radius:5px;padding:13px;margin-top:13px;color:var(--warning)}.unknown-note>svg{flex-shrink:0;margin-top:2px}.unknown-note p{font-size:14px;line-height:1.9;margin:0}.unknown-note strong{display:block;font-size:14px;font-weight:600;margin-bottom:4px}.unknown-note p>span{display:block;color:#7e6b4d}.quota-state-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:12px 0;border-top:1px solid var(--line)}.quota-state-row>span{font-size:16px;font-variant-numeric:tabular-nums;font-weight:550}.quota-state-row small{font-size:12px;color:var(--muted);font-weight:400;margin-left:3px}.no-states{font-size:14px;color:var(--muted);margin:0;padding:14px 0 10px}
@media(max-width:1050px){.quota-summary{gap:12px}.quota-number{padding:19px}.quota-number>strong{font-size:25px}.quota-details{gap:18px}.budget-panel,.resource-panel,.state-panel{padding:21px}}
@media(max-width:767px){.quota-summary{grid-template-columns:minmax(0,1fr);gap:10px;margin-bottom:18px}.quota-number{position:relative;padding:18px 19px;display:grid;grid-template-columns:1fr auto;column-gap:15px;align-items:center}.quota-label{font-size:14px}.quota-label svg{display:none}.quota-number>strong{grid-column:2;grid-row:1/3;margin:0;font-size:25px}.quota-number>p{font-size:12px;max-width:190px;margin-top:5px}.quota-details{grid-template-columns:minmax(0,1fr);gap:18px}.budget-panel,.resource-panel,.state-panel{padding:20px}.budget-panel{margin-bottom:18px}.section-heading{gap:12px;align-items:flex-start;margin-bottom:20px}.section-heading h2{font-size:15px}.available-amount{font-size:12px}.available-amount strong{display:block;font-size:14px;margin:5px 0 0}.budget-legend{gap:10px 17px;font-size:12px}.budget-note{font-size:14px}.resource-list>div{padding:15px 0}}
</style>
